graphql:
{
  kpis(
    filter: {region: "AMER"}
    aggregateBy: LINE
    timeRange: {start: "2026-10-01", end: "2026-10-31"}
    orderBy: {metric: OEE, direction: DESC}
    limit: 10
  ) {
    line
    oee
  }
}

{
  kpis(
    aggregateBy: PLANT
    timeRange: {start: "2026-10-01", end: "2026-10-31"}
    orderBy: {metric: SCRAP_RATE, direction: DESC}
    limit: 1
  ) {
    plant
    scrap_rate
  }
}

